const e="Regulations for All Students",t={verified:!1,lastEdited:"9/9/2026",branch:"main",tablesPresent:0,tablesConsumed:0,tablesOnPage:0,tablesExcluded:0,sourceUrl:"https://catalog.northeastern.edu/graduate/social-sciences-humanities/general-regulations/regulations-for-all-students/",panes:[""],planOfStudyCourses:[],verification:{level:"partial",kind:"grad",score:.83,checkedAt:"2026-09-10",sourceUrl:"https://catalog.northeastern.edu/graduate/social-sciences-humanities/general-regulations/regulations-for-all-students/",sourcesAvailable:["requirement-tables","course-catalog"],counters:{tablesUnaccounted:0,leakedMarkers:0,unenumeratedSections:1,duplicateSectionTitles:0,duplicateConcentrationTitles:0,zeroTotal:1,unknownCourses:0,planUnexplained:0,impossibleSections:0},discrepancies:[{check:"missing-total-credits",severity:"medium",message:"the catalog page states no total credit requirement",detail:[{key:"noTotal"}],overflow:0},{check:"unenumerated-sections",severity:"info",message:"1 section(s) state a credit requirement whose courses the catalog does not list, so completion of those cannot be checked automatically",detail:[{key:"unenumeratedSection",params:{title:"Awards",sh:6}}],overflow:0}]}},a=0,s=2027,i=[{type:"SECTION",title:"Awards",creditsRequired:6,minRequirementCount:1,requirements:[],notes:["Only those students who are registered in degree programs are eligible for awards. Award recipients will receive an official award letter from the CSSH Graduate Office. Please pay attention to this letter as it is an official contract that should be read carefully. In order to maintain awards, students must be making satisfactory progress toward their degrees. Please refer to the Satisfactory Academic Progress section below for more information.","Students receiving a Stipended Graduate Assistantship must be in full-time status and be registered for a minimum of 6 semester hours. The standard duration of the SGA funding window is five years beginning from the time of admission and is not changed based on the source of funding or if the stipend is declined in any given semester(s). The health plan fee (NUSHP) is covered by the SGA award whereas the University Health and Counseling Services fee is not. Students on an SGA must be available to come to campus during normal business hours and are expected to spend 20 hours per week supporting their assignment. Unsatisfactory progress in either the graduate program or performance in assistantship-related duties or any deviation from the above may result in the early termination of the assistantship. Near the end of each funded term, student performance will be evaluated by their assignment supervisor and that evaluation will be filed with the CSSH Graduate Office.","CSSH Dean’s Scholarship and Excellence Fellowship recipients must be in full-time status and be registered for a minimum of 8 semester hours."]}],r={name:e,metadata:t,totalCreditsRequired:a,yearVersion:s,requirementSections:i};export{r as default,t as metadata,e as name,i as requirementSections,a as totalCreditsRequired,s as yearVersion};
